const sourceTopic = msg.topic;
const raw = msg.payload;
try {
  const reading = typeof raw === 'string' ? JSON.parse(raw) : raw;
  const processor = global.get('edgeProcessor');
  const event = processor.processShelf(reading);
  const save = global.get('saveEdgeState');
  if (save) save(processor);
  if (!event) return null;
  msg.topic = 'shelfsense/events/' + event.type;
  const sign = global.get('signBusinessEvent');
  msg.payload = JSON.stringify(sign ? sign(event) : event);
  return [msg, null];
} catch (error) {
  msg.topic = 'shelfsense/dead-letter';
  msg.payload = JSON.stringify({ sourceTopic, reason: error.message, payload: raw, ts: Date.now() });
  return [null, msg];
}

